#!/usr/bin/env bash
# Generated by scripts/ci/vm-lab.py from the lab files. Do not edit; change
# the lab files and run: python3 scripts/ci/vm-lab.py <lab directory>
# astrona pipes this file alone into the lab VM, where it runs as the VM
# administrator user. It builds the one-node kubeadm cluster, writes the lab
# files to /opt/astrona-lab and runs bootstrap/setup.sh from there.
set -euo pipefail
cluster="astro-ats-035-lab-030-01-02"
# The learner logs in as student, so student gets the admin kubeconfig too.
kube_users=(--user "$(id -un)")
getent passwd student >/dev/null && kube_users+=(--user student)
sudo /usr/local/sbin/astrona-kubeadm-init --cluster-name "$cluster" "${kube_users[@]}"
lab="/opt/astrona-lab"
sudo rm -rf "$lab"
write_file() {
  sudo mkdir -p "$(dirname "$lab/$2")"
  sudo tee "$lab/$2" >/dev/null
  sudo chmod "$1" "$lab/$2"
}
